INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'nachgeschaltete_stufe', '{"variante_spur":"nachgeschaltete_stufe"}'::jsonb, NULL, 'd) Nachgeschaltete Adsorptionsstufe: keine allgemein gültigen Bemessungsvorgaben; RBF nach DWA-A 178 unverändert', 3, '{"q_dr_rbf":null,"q_dr_comparator":null,"q_dr_text":null,"h_fk_min_m":null,"h_fk_text":null,"beschickungsdauer_max_h":null,"trockenzeit_h":null,"segmente_erfahrung":null,"v_segment_text":null,"hinweis":"Für die nachgeschaltete Reinigungsstufe können bisher keine allgemein gültigen Bemessungsvorgaben empfohlen werden."}'::jsonb, 'Zu d) Für die nachgeschaltete Reinigungsstufe können bisher keine allgemein gültigen Bemessungsvorgaben empfohlen werden. Diese sollte jedoch gleichmäßig mit dem gedrosselten Ablauf des RBF beschickt werden. Bei der Nachschaltung einer Adsorptionsstufe bleibt der Aufbau des RBF unverändert gegenüber den Vorgaben aus dem Arbeitsblatt DWA-A 178:2019. Die nachgeschaltete Adsorptionsstufe muss separat bemessen werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_LIMITS_SPUR'
