INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'mikroorganismen', '{"sonderanwendung":"mikroorganismen"}'::jsonb, NULL, 'Mikroorganismen: q_Dr,RBF = 0,01 l/(s·m²) bei Volleinstau; h_FK ≥ 1,0 m (sollte)', 2, '{"q_dr_rbf":0.01,"q_dr_comparator":"=","q_dr_modal":"sicherzustellen","h_fk_min_m":1,"h_fk_comparator":"≥","h_fk_modal":"sollte","h_fk_carbonat_m":null,"hinweis":null}'::jsonb, 'Die Bemessungsvorgaben und die Empfehlungen zur Nachweisführung gelten gemäß Arbeitsblatt DWA-A 178:2019. Abweichend ist jedoch sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\mathrm{Dr}, \mathrm{RBF}}=0,01 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Das Drosselorgan kann ungeregelt ausgeführt werden (WaldhoFF 2008).

Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018).' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_LIMITS_APP'
