SELECT id, 'organische_belastung', '{"sonderanwendung":"organische_belastung"}'::jsonb, NULL, 'Hohe organische Belastung: Bemessung über die CSB-Fracht (S5_4_3_ORG); h_FK / q_Dr,RBF nach DWA-A 178', 3, '{"q_dr_rbf":null,"q_dr_comparator":null,"q_dr_modal":null,"h_fk_min_m":null,"h_fk_comparator":null,"h_fk_modal":null,"h_fk_carbonat_m":null,"hinweis":"Die Bemessung erfolgt über die CSB-Fracht in Anlehnung an das Arbeitsblatt DWA-A 262:2017 in 4.3.3.2."}'::jsonb, 'Für einen dauerhaften Betrieb und einen ausreichenden CSB-Abbau ist die auf die Filterfläche aufgetragene Feststoff- und CSB-Fracht zu begrenzen. Die Bemessung erfolgt über die CSB-Fracht in Anlehnung an das Arbeitsblatt DWA-A 262:2017 in 4.3.3.2.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_LIMITS_APP'
