INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'klein_rbf', '{"sonderanwendung":"klein_rbf"}'::jsonb, NULL, 'Klein-RBF: h_FK ≥ 0,25 m; mit Carbonatschicht h_FK,CaCO3 ≥ 0,10 m auf 0,2 m verringerbar', 4, '{"q_dr_rbf":null,"q_dr_comparator":null,"q_dr_modal":null,"h_fk_min_m":0.25,"h_fk_comparator":"≥","h_fk_modal":"beträgt","h_fk_carbonat_m":0.2,"hinweis":"Drosselung über den Fließwiderstand des Filtermaterials (keine Drosselabflussspende)"}'::jsonb, 'Der Filterkörper muss einschichtig mit ebener Oberfläche hergestellt werden. Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand $h_{\mathrm{FK}} \geqslant 0,25 \mathrm{~m}$. Hinweise zur Filterstabilität und dem nicht zulässigen Einsatz von Geotextilien sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen.

\section*{Filtermaterial}

Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_LIMITS_APP'
