UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_LIMITS_APP' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-187', '2025-09', 'S5_1_3_1_P', 'P-Rückhalt: Bemessungs- und Materialkennwerte je Verfahrensvariante (§5.1.3.1, §5.1.3.2, §5.1.3.4)', '§5.1.3.1, §5.1.3.2, §5.1.3.4', NULL, ARRAY['variante_p','parameter']::text[], '[{"name":"wert","type":"number"},{"name":"unit","type":"string"},{"name":"comparator","type":"string"},{"name":"modal","type":"string"},{"name":"text","type":"string"}]'::jsonb, 'locked', 'Grundsätzlich ist der Anteil der Eisenhydroxidzugabe von der Zulaufkonzentration, der angestrebten Ablaufkonzentration, der P-Bindungskapazität und der kalkulatorischen Betriebszeit abhängig. Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. Liegen besondere Anforderungen an die zu erreichende Ablaufkonzentration, die Betriebszeit, oder die Wirtschaftlichkeit der Anlage vor, ist es empfehlenswert, den einzumischenden Eisenhydoxidanteil über die mittlere Jahreszulauffracht rechnerisch zu bestimmen.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'faellung_filterzulauf|beta_min', '{"variante_p":"faellung_filterzulauf","parameter":"beta_min"}'::jsonb, 'faellung_filterzulauf', 'Beta-Wert (Fällmittel Eisen-III-Salz) ≥ 4', 0, '{"wert":4,"unit":"-","comparator":"≥","modal":"kann","text":"mit einem Beta-Wert von $\\geqslant 4$ angesetzt werden"}'::jsonb, 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Basierend auf einer mittleren $\mathrm{PO}_{4}$-Zulaufkonzentration von $S_{\text {P04-P, aM }}=0,5 \mathrm{mg} / \mathrm{l}$ kann die Menge des Fällmittels (Eisen-III-Salz) mit einem Beta-Wert von $\geqslant 4$ angesetzt werden. Diese Dosiermenge ist im laufenden Betrieb hinsichtlich der Zielkonzentration und der Fällmittelausnutzung zu optimieren. Die Dosierung muss an einer Stelle erfolgen, bei der eine ausreichende Durchmischung gewährleistet ist.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'faellung_filterzulauf|s_po4p_am', '{"variante_p":"faellung_filterzulauf","parameter":"s_po4p_am"}'::jsonb, 'faellung_filterzulauf', 'mittlere PO4-Zulaufkonzentration S_PO4-P,aM = 0,5 mg/l (Bemessungsbasis)', 1, '{"wert":0.5,"unit":"mg/l","comparator":"=","modal":"Basis","text":"$S_{\\text {P04-P, aM }}=0,5 \\mathrm{mg} / \\mathrm{l}$"}'::jsonb, 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Basierend auf einer mittleren $\mathrm{PO}_{4}$-Zulaufkonzentration von $S_{\text {P04-P, aM }}=0,5 \mathrm{mg} / \mathrm{l}$ kann die Menge des Fällmittels (Eisen-III-Salz) mit einem Beta-Wert von $\geqslant 4$ angesetzt werden. Diese Dosiermenge ist im laufenden Betrieb hinsichtlich der Zielkonzentration und der Fällmittelausnutzung zu optimieren. Die Dosierung muss an einer Stelle erfolgen, bei der eine ausreichende Durchmischung gewährleistet ist.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'faellung_filterzulauf|pufferschicht_cm', '{"variante_p":"faellung_filterzulauf","parameter":"pufferschicht_cm"}'::jsonb, 'faellung_filterzulauf', 'Pufferschicht aus gewaschenem Carbonatbrechsand ca. 5 cm', 2, '{"wert":5,"unit":"cm","comparator":"ca.","modal":"sollte","text":"ca. 5 cm hohe Pufferschicht aus gewaschenem Carbonatbrechsand"}'::jsonb, 'Der RBF sollte zusätzlich zur Deckschicht und der Carbonatausstattung nach Arbeitsblatt DWAA 178:2019 mit einer ca. 5 cm hohe Pufferschicht aus gewaschenem Carbonatbrechsand ( $>0,06 \mathrm{~mm}$ bis 2 mm ) ausgestattet werden. Diese Schicht dient der Vermeidung der Filtersedimentversauerung durch das Fällmittel. Im Neubau sollte die Pufferschicht zwischen Filtermaterial und Deckschicht eingebaut werden. Bei der Nachrüstung kann der Carbonatbrechsand außerhalb der Vegetationsperiode auf das vorhandene Filtersediment aufgebracht werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'melioration_filtermaterial|fe_massenanteil_pct', '{"variante_p":"melioration_filtermaterial","parameter":"fe_massenanteil_pct"}'::jsonb, 'melioration_filtermaterial', 'Eisenhydroxidmassenanteil 7 % (gute Ergebnisse)', 3, '{"wert":7,"unit":"%","comparator":"=","modal":"kann","text":"bei einem Eisenhydroxidmassenanteil von 7 \\% gute Ergebnisse"}'::jsonb, 'Grundsätzlich ist der Anteil der Eisenhydroxidzugabe von der Zulaufkonzentration, der angestrebten Ablaufkonzentration, der P-Bindungskapazität und der kalkulatorischen Betriebszeit abhängig. Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. Liegen besondere Anforderungen an die zu erreichende Ablaufkonzentration, die Betriebszeit, oder die Wirtschaftlichkeit der Anlage vor, ist es empfehlenswert, den einzumischenden Eisenhydoxidanteil über die mittlere Jahreszulauffracht rechnerisch zu bestimmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'melioration_filtermaterial|fe_gehalt_min_pct', '{"variante_p":"melioration_filtermaterial","parameter":"fe_gehalt_min_pct"}'::jsonb, 'melioration_filtermaterial', 'Eisengehalt Fe > 35 %', 4, '{"wert":35,"unit":"%","comparator":">","modal":"einzuhalten","text":"Eisengehalt von $\\mathrm{Fe}>35 \\%$"}'::jsonb, 'Grundsätzlich ist der Anteil der Eisenhydroxidzugabe von der Zulaufkonzentration, der angestrebten Ablaufkonzentration, der P-Bindungskapazität und der kalkulatorischen Betriebszeit abhängig. Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. Liegen besondere Anforderungen an die zu erreichende Ablaufkonzentration, die Betriebszeit, oder die Wirtschaftlichkeit der Anlage vor, ist es empfehlenswert, den einzumischenden Eisenhydoxidanteil über die mittlere Jahreszulauffracht rechnerisch zu bestimmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
