INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'melioration_filtermaterial|p_grund_beladung_max', '{"variante_p":"melioration_filtermaterial","parameter":"p_grund_beladung_max"}'::jsonb, 'melioration_filtermaterial', 'P-Grundbeladung < 0,2 g/kg im Zuschlagstoff', 5, '{"wert":0.2,"unit":"g/kg","comparator":"<","modal":"einzuhalten","text":"P-Grundbeladung von $<0,2 \\mathrm{~g} / \\mathrm{kg}$"}'::jsonb, 'Grundsätzlich ist der Anteil der Eisenhydroxidzugabe von der Zulaufkonzentration, der angestrebten Ablaufkonzentration, der P-Bindungskapazität und der kalkulatorischen Betriebszeit abhängig. Untersuchungen an bestehenden Filtern im Trenn- und Mischsystem und Säulenversuche im Labor haben gezeigt, dass bei einem Eisenhydroxidmassenanteil von 7 \% gute Ergebnisse in Bezug auf die oben genannten Kriterien erreicht werden können. Für das Eisenhydroxid ist ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbeladung von $<0,2 \mathrm{~g} / \mathrm{kg}$ im Zuschlagstoff einzuhalten. Liegen besondere Anforderungen an die zu erreichende Ablaufkonzentration, die Betriebszeit, oder die Wirtschaftlichkeit der Anlage vor, ist es empfehlenswert, den einzumischenden Eisenhydoxidanteil über die mittlere Jahreszulauffracht rechnerisch zu bestimmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
