INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'melioration_filtermaterial|feinmassenanteil_max_pct', '{"variante_p":"melioration_filtermaterial","parameter":"feinmassenanteil_max_pct"}'::jsonb, 'melioration_filtermaterial', 'Feinmassenanteil > 5 % ⇒ hydraulische Eignung durch Versuche belegen', 6, '{"wert":5,"unit":"%","comparator":">","modal":"muss","text":"Bei einem Feinmassenanteil > $5 \\%$ im fertig gemischten Filtermaterial muss die hydraulische Eignung des Filtermaterials durch Versuche belegt werden"}'::jsonb, 'Bei der Melioration mit Eisenhydroxid kommt es zu einer Erhöhung des Feinkornanteils im fertig gemischten Filtermaterial, da das Eisenhydroxid in der Regel einen hohen Feinkornanteil aufweist. Bei einem Feinmassenanteil > $5 \%$ im fertig gemischten Filtermaterial muss die hydraulische Eignung des Filtermaterials durch Versuche belegt werden. Die Grundanforderungen gemäß Arbeitsblatt DWA-A 178:2019 sind einzuhalten.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'melioration_filtermaterial|fallhoehe_max_m', '{"variante_p":"melioration_filtermaterial","parameter":"fallhoehe_max_m"}'::jsonb, 'melioration_filtermaterial', 'Fallhöhe beim Einbau ≤ 1,0 m', 7, '{"wert":1,"unit":"m","comparator":"≤","modal":"einzuhalten","text":"Fallhöhen von $\\leqslant 1,0 \\mathrm{~m}$ einzuhalten"}'::jsonb, 'Um eine gleichmäßige Filterdurchlässigkeit des Filters zu gewährleisten, ist das meliorierte Filtermaterial möglichst verdichtungsfrei einzubauen. Dies kann zum Beispiel über einen Teleskopausleger erfolgen. Zur Gewährleistung des entmischungsfreien Einbaus sind Fallhöhen von $\leqslant 1,0 \mathrm{~m}$ einzuhalten.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'nachgeschaltete_sorptionsstufe|ebct_min_min', '{"variante_p":"nachgeschaltete_sorptionsstufe","parameter":"ebct_min_min"}'::jsonb, 'nachgeschaltete_sorptionsstufe', 'Filterkontaktzeit EBCT ≥ 15 min', 8, '{"wert":15,"unit":"min","comparator":"≥","modal":"kann","text":"Filterkontaktzeiten (EBCT) $\\geqslant 15 \\mathrm{~min}$"}'::jsonb, 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'nachgeschaltete_sorptionsstufe|v_filter_auf_max', '{"variante_p":"nachgeschaltete_sorptionsstufe","parameter":"v_filter_auf_max"}'::jsonb, 'nachgeschaltete_sorptionsstufe', 'maximale Filtergeschwindigkeit (Aufstrom) < 5,0 m/h', 9, '{"wert":5,"unit":"m/h","comparator":"<","modal":"kann","text":"maximale Filtergeschwindigkeiten $<5,0 \\mathrm{~m} / \\mathrm{h}$"}'::jsonb, 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
