INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'nachgeschaltete_sorptionsstufe|sorptionsstufen_min', '{"variante_p":"nachgeschaltete_sorptionsstufe","parameter":"sorptionsstufen_min"}'::jsonb, 'nachgeschaltete_sorptionsstufe', 'Reihenschaltung von mindestens zwei Sorptionsstufen', 12, '{"wert":2,"unit":"-","comparator":"≥","modal":"empfohlen","text":"Reihenschaltung von mindestens zwei Sorptionsstufen empfohlen"}'::jsonb, 'Um das P-Bindepotenzial des Sorptionsmittels auszunutzen und die Einhaltung der Zielkonzentration dauerhaft sicherstellen zu können, wird eine Reihenschaltung von mindestens zwei Sorptionsstufen empfohlen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
