SELECT id, 'nachgeschaltete_sorptionsstufe|fe_gehalt_min_pct', '{"variante_p":"nachgeschaltete_sorptionsstufe","parameter":"fe_gehalt_min_pct"}'::jsonb, 'nachgeschaltete_sorptionsstufe', 'Eisengehalt Fe > 35 % (Sorptionsmittel)', 13, '{"wert":35,"unit":"%","comparator":">","modal":"gelten","text":"Eisengehalt von $\\mathrm{Fe}>35 \\%$"}'::jsonb, 'Als Anforderung für den adsorbierenden Stoff in Form von Eisenhydroxid gelten neben der Schadstofffreiheit gemäß LAGA (2003) ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbelastung von $C_{\mathrm{P}}<0,2 \mathrm{~g} / \mathrm{kg}$.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
