SELECT id, 'nachgeschaltete_sorptionsstufe|p_grund_beladung_max', '{"variante_p":"nachgeschaltete_sorptionsstufe","parameter":"p_grund_beladung_max"}'::jsonb, 'nachgeschaltete_sorptionsstufe', 'P-Grundbelastung C_P < 0,2 g/kg (Sorptionsmittel)', 14, '{"wert":0.2,"unit":"g/kg","comparator":"<","modal":"gelten","text":"P-Grundbelastung von $C_{\\mathrm{P}}<0,2 \\mathrm{~g} / \\mathrm{kg}$"}'::jsonb, 'Als Anforderung für den adsorbierenden Stoff in Form von Eisenhydroxid gelten neben der Schadstofffreiheit gemäß LAGA (2003) ein Eisengehalt von $\mathrm{Fe}>35 \%$ und eine P-Grundbelastung von $C_{\mathrm{P}}<0,2 \mathrm{~g} / \mathrm{kg}$.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_1_3_1_P'
