INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-187', '2025-09', 'S5_4_3_ORG', 'Hohe organische Belastung: Bemessungsvorgaben (§5.4.2.2.2, §5.4.3, §5.4.4)', '§5.4.2.2.2, §5.4.3, §5.4.4', NULL, ARRAY['parameter']::text[], '[{"name":"wert","type":"number"},{"name":"unit","type":"string"},{"name":"comparator","type":"string"},{"name":"modal","type":"string"},{"name":"text","type":"string"}]'::jsonb, 'locked', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'csb_trennung', '{"parameter":"csb_trennung"}'::jsonb, NULL, 'CSB-Konzentration > 3.000 mg/l ⇒ Trennung Lagerflächen / Verkehrsflächen', 0, '{"wert":3000,"unit":"mg/l","comparator":">","modal":"müssen","text":"Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \\mathrm{mg} / \\mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden"}'::jsonb, 'Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). Das Niederschlagswasser der Betriebsflächen darf in die RBFA eingeleitet werden. Das Sickerwasser ist für eine Behandlung mit einem RBF zu hoch belastet und darf daher nicht in die RBFA eingeleitet werden. Es ist auch sicherzustellen, dass keine größeren Mengen an organischem Material (zum Beispiel durch Zwischenlagerung oder Verladung) und auch kein oberflächlich abfließendes Sickerwasser auf die Betriebsflächen gelangt. Sofern dieses der Fall ist, sind bauliche Veränderungen an der Flächenentwässerung durchzuführen oder es muss ein anderes Behandlungsverfahren gewählt werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'wirkungsgrad', '{"parameter":"wirkungsgrad"}'::jsonb, NULL, 'Vollstrombehandlung mit 100 % hydraulischem Wirkungsgrad', 1, '{"wert":100,"unit":"%","comparator":"=","modal":"muss","text":"muss der RBF auf eine Vollstrombehandlung mit $100 \\%$ hydraulischem Wirkungsgrad ausgelegt werden"}'::jsonb, 'und der Notüberlauf (NÜ) auf der gegenüberliegenden Seite des Zulaufs angeordnet werden. Wegen der weitergehenden Sedimentationsprozesse und der Raumfilterwirkung des Bewuchses vergrößert ein gegenüber der Zulaufseite angeordneter Filterüberlauf die Reinigungsleistung der RBFA. Wegen der hohen zu erwartenden Stoffkonzentrationen muss der RBF auf eine Vollstrombehandlung mit $100 \%$ hydraulischem Wirkungsgrad ausgelegt werden. Der Notüberlauf des Filters stellt nur eine zusätzliche Sicherheit zum Schutz der Anlage dar.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'q_krit', '{"parameter":"q_krit"}'::jsonb, NULL, 'Bemessung der Vorstufe für q_krit = 60 l/(s·ha)', 2, '{"wert":60,"unit":"l/(s·ha)","comparator":"=","modal":"sollte","text":"Die Bemessung sollte für $q_{\\text {krit }}=60 \\mathrm{l} /(\\mathrm{s} \\cdot \\mathrm{ha})$ erfolgen"}'::jsonb, 'Die Gestaltung der Vorstufe muss gemäß Arbeitsblatt DWA-A 166:2013 und Merkblatt DWAM 176:2013 als Durchlaufbecken ohne Dauerstau mit einem vorgeschalteten Beckenüberlauf ausgeführt werden (Bild 4). Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. Wegen der großen Feststoffbelastung muss die Abflussbegrenzung im Beckenüberlauf auf einfache und robuste Art erfolgen (Schlitz, Rohrdrossel).' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'q_a_max', '{"parameter":"q_a_max"}'::jsonb, NULL, 'maximale Oberflächenbeschickung der Vorstufe q_A,max = 4 m/h', 3, '{"wert":4,"unit":"m/h","comparator":"≤","modal":"muss","text":"muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\\mathrm{A}, \\max }=4 \\mathrm{~m} / \\mathrm{h}$ bemessen werden"}'::jsonb, 'Die Gestaltung der Vorstufe muss gemäß Arbeitsblatt DWA-A 166:2013 und Merkblatt DWAM 176:2013 als Durchlaufbecken ohne Dauerstau mit einem vorgeschalteten Beckenüberlauf ausgeführt werden (Bild 4). Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. Wegen der großen Feststoffbelastung muss die Abflussbegrenzung im Beckenüberlauf auf einfache und robuste Art erfolgen (Schlitz, Rohrdrossel).' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'v_vorstufe_min', '{"parameter":"v_vorstufe_min"}'::jsonb, NULL, 'Mindestvolumen der Vorstufe 50 m³', 4, '{"wert":50,"unit":"m³","comparator":"≥","modal":"empfohlen","text":"Es wird ein Mindestvolumen von $50 \\mathrm{~m}^{3}$ empfohlen"}'::jsonb, 'Die Gestaltung der Vorstufe muss gemäß Arbeitsblatt DWA-A 166:2013 und Merkblatt DWAM 176:2013 als Durchlaufbecken ohne Dauerstau mit einem vorgeschalteten Beckenüberlauf ausgeführt werden (Bild 4). Die Bemessung sollte für $q_{\text {krit }}=60 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ erfolgen. Für einen effektiven Feststoffrückhalt muss die Vorstufe auf eine maximale Oberflächenbeschickung von $q_{\mathrm{A}, \max }=4 \mathrm{~m} / \mathrm{h}$ bemessen werden. Es wird ein Mindestvolumen von $50 \mathrm{~m}^{3}$ empfohlen. Wegen der großen Feststoffbelastung muss die Abflussbegrenzung im Beckenüberlauf auf einfache und robuste Art erfolgen (Schlitz, Rohrdrossel).' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'b_csb_max', '{"parameter":"b_csb_max"}'::jsonb, NULL, 'CSB-Fracht ≤ 20 g CSB/(m²·d) bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt', 5, '{"wert":20,"unit":"g/(m²·d)","comparator":"≤","modal":"ist … zu bemessen","text":"Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\\leqslant 20 \\mathrm{~g}$ CSB $/\\left(\\mathrm{m}^{2} \\cdot \\mathrm{~d}\\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt"}'::jsonb, 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'a_f_pro_aeb', '{"parameter":"a_f_pro_aeb"}'::jsonb, NULL, 'Gesamtfilterfläche ≥ 750 m²/ha A_E,b (wenn keine Daten vorliegen)', 6, '{"wert":750,"unit":"m²/ha","comparator":"≥","modal":"muss","text":"Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \\mathrm{~m}^{2} / \\mathrm{ha} A_{\\mathrm{E}, \\mathrm{b}}$ betragen"}'::jsonb, 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'teilfilter_multiple', '{"parameter":"teilfilter_multiple"}'::jsonb, NULL, 'Aufteilung in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken', 7, '{"wert":4,"unit":"-","comparator":"Vielfaches","modal":"wird","text":"Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt"}'::jsonb, 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'teilfilter_in_betrieb', '{"parameter":"teilfilter_in_betrieb"}'::jsonb, NULL, 'jeweils drei Teilfilterbecken gleichzeitig in Betrieb, eins in Betriebspause', 8, '{"wert":3,"unit":"-","comparator":"=","modal":"sind","text":"Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause"}'::jsonb, 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'foerderleistung', '{"parameter":"foerderleistung"}'::jsonb, NULL, 'Förderleistung der Beschickung ≥ 6 l/(m²·min) bezogen auf die jeweils beschickte Filterfläche', 9, '{"wert":6,"unit":"l/(m²·min)","comparator":"≥","modal":"muss","text":"muss eine Förderleistung von mindestens $6 \\mathrm{l} /\\left(\\mathrm{m}^{2} \\cdot \\mathrm{~min}\\right)$ bezogen auf die jeweils beschickte Filterfläche betragen"}'::jsonb, 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'beschickung_pro_ereignis', '{"parameter":"beschickung_pro_ereignis"}'::jsonb, NULL, 'Beschickung 20 l/m² je Ereignis bezogen auf die jeweils beschickte Filterfläche', 10, '{"wert":20,"unit":"l/m²","comparator":"=","modal":"sollten","text":"Pro Beschickungsereignis sollten $20 \\mathrm{l} / \\mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden"}'::jsonb, 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'austritt_max', '{"parameter":"austritt_max"}'::jsonb, NULL, 'beschickte Filterfläche ≤ 1 m² je Austrittsöffnung', 11, '{"wert":1,"unit":"m²/Öffnung","comparator":"≤","modal":"sollte","text":"Die beschickte Filterfläche sollte $\\leqslant 1 \\mathrm{~m}^{2}$ /Austrittsöffnung betragen"}'::jsonb, 'Die Beschickung des Retentionsfilterbeckens erfolgt anders als sonst üblich kontinuierlich intervallweise, solange noch Wasser in der Vorstufe gespeichert ist. Es muss ein gleichmäßiges engmaschiges Verteilungsnetz auf der Filterbeckenoberfläche installiert werden. Die beschickte Filterfläche sollte $\leqslant 1 \mathrm{~m}^{2}$ /Austrittsöffnung betragen. Weitere Hinweise sind im Arbeitsblatt DWA-A 262:2017 zu finden. Das Beschickungssystem muss hydraulisch berechnet werden, um eine gleichmäßige Beschickung der gesamten Filteroberfläche zu gewährleisten.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_4_3_ORG' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-187', '2025-09', 'S5_5_KLEIN', 'Dezentrale Klein-Retentionsbodenfilterbecken: Kennwerte (§5.5.2, §5.5.3.2.2, §5.5.4)', '§5.5.2, §5.5.3.2.2, §5.5.4', NULL, ARRAY['parameter']::text[], '[{"name":"wert","type":"number"},{"name":"unit","type":"string"},{"name":"comparator","type":"string"},{"name":"modal","type":"string"},{"name":"text","type":"string"}]'::jsonb, 'locked', 'Der Filterkörper muss einschichtig mit ebener Oberfläche hergestellt werden. Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand $h_{\mathrm{FK}} \geqslant 0,25 \mathrm{~m}$. Hinweise zur Filterstabilität und dem nicht zulässigen Einsatz von Geotextilien sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'a_b_a_max_ha', '{"parameter":"a_b_a_max_ha"}'::jsonb, NULL, 'Anwendungsbereich: angeschlossene befestigte Fläche A_b,a < 1 ha', 0, '{"wert":1,"unit":"ha","comparator":"<","modal":"beschränkt sich","text":"befestigten, angeschlossenen Fläche von $A_{\\mathrm{b}, \\mathrm{a}}<1$ ha"}'::jsonb, 'Der Anwendungsbereich dieser RBF beschränkt sich auf innerörtliche Verkehrsflächen (Straßen, Wege, Plätze) mit einer befestigten, angeschlossenen Fläche von $A_{\mathrm{b}, \mathrm{a}}<1$ ha. Neben der Anordnung im Straßenseitenraum können beispielsweise auch Verkehrsinseln genutzt werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_rr_min', '{"parameter":"h_rr_min"}'::jsonb, NULL, 'nutzbare Einstauhöhe h_RR ≥ 0,2 m', 1, '{"wert":0.2,"unit":"m","comparator":"≥","modal":"beträgt","text":"Die nutzbare Einstauhöhe beträgt $h_{R R} \\geqslant 0,2 \\mathrm{~m}$"}'::jsonb, 'Der Retentionsraum dient der Zwischenspeicherung und der Sedimentation der durch Filtration zu behandelnden Regenwasserabflüsse. Die nutzbare Einstauhöhe beträgt $h_{R R} \geqslant 0,2 \mathrm{~m}$.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'deckschicht_cm', '{"parameter":"deckschicht_cm"}'::jsonb, NULL, 'Deckschicht 5 cm (kantengerundetes / gebrochenes mineralisches Material 2 mm bis 8 mm)', 2, '{"wert":5,"unit":"cm","comparator":"=","modal":"besteht aus","text":"Sie besteht aus einer 5 cm starken Schicht aus kantengerundetem oder gebrochenem mineralischem Material ( 2 mm bis 8 mm )"}'::jsonb, 'Die Deckschicht erlaubt die Begehbarkeit des Filters und schützt die Bodenfilteroberfläche vor äußerer Kolmation, solange die Filtervegetation noch nicht etabliert ist oder keine Filtervegetation vorgesehen ist. Sie besteht aus einer 5 cm starken Schicht aus kantengerundetem oder gebrochenem mineralischem Material ( 2 mm bis 8 mm ). Das Material der Deckschicht muss frost- und tausalzbeständig sein.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_fk_min', '{"parameter":"h_fk_min"}'::jsonb, NULL, 'Höhe des Filterkörpers (konsolidiert) h_FK ≥ 0,25 m', 3, '{"wert":0.25,"unit":"m","comparator":"≥","modal":"beträgt","text":"Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand $h_{\\mathrm{FK}} \\geqslant 0,25 \\mathrm{~m}$"}'::jsonb, 'Der Filterkörper muss einschichtig mit ebener Oberfläche hergestellt werden. Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand $h_{\mathrm{FK}} \geqslant 0,25 \mathrm{~m}$. Hinweise zur Filterstabilität und dem nicht zulässigen Einsatz von Geotextilien sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'caco3_filter_min_pct', '{"parameter":"caco3_filter_min_pct"}'::jsonb, NULL, 'CaCO3-Massenanteil des Filtermaterials ≥ 20 % (DWA-A 178)', 4, '{"wert":20,"unit":"%","comparator":"≥","modal":"einzuhalten","text":"ein $\\mathrm{CaCO}_{3}$-Massenanteil von $\\geqslant 20 \\%$ einzuhalten ist"}'::jsonb, 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_fk_caco3_min', '{"parameter":"h_fk_caco3_min"}'::jsonb, NULL, 'Carbonatschicht h_FK,CaCO3 ≥ 0,10 m (Carbonatbrechsand 2 mm bis 8 mm)', 5, '{"wert":0.1,"unit":"m","comparator":"≥","modal":"kann","text":"Carbonatschicht mit einer Schichtstärke $h_{\\mathrm{FK}}, \\mathrm{CaCO}_{3} \\geqslant 0,10 \\mathrm{~m}$"}'::jsonb, 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'caco3_carbo_pct', '{"parameter":"caco3_carbo_pct"}'::jsonb, NULL, 'CaCO3-Massenanteil des Carbonatbrechsands 80 %', 6, '{"wert":80,"unit":"%","comparator":"=","modal":"kann","text":"mit einem $\\mathrm{CaCO}_{3}$-Massenanteil von $80 \\%$ hergestellt werden"}'::jsonb, 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
