INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_fk_carbonat', '{"parameter":"h_fk_carbonat"}'::jsonb, NULL, 'mit Carbonatschicht: Filterstärke auf h_FK 0,2 m verringerbar', 7, '{"wert":0.2,"unit":"m","comparator":"≥","modal":"kann","text":"kann die Filterstärke auf $h_{F K} 0,2 \\mathrm{~m}$ verringert werden"}'::jsonb, 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
