INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'draen_dn_min', '{"parameter":"draen_dn_min"}'::jsonb, NULL, 'Dränage mindestens DN 50, ungedrosselt', 8, '{"wert":50,"unit":"DN","comparator":"≥","modal":"muss","text":"Die Dränage muss mindestens in DN 50 ungedrosselt ausgeführt werden"}'::jsonb, 'Die Dränage muss mindestens in DN 50 ungedrosselt ausgeführt werden. Die Drosselung erfolgt über den Fließwiderstand des Filtermaterials. Die Schichtdicke des Dränmaterials sollte mindestens $h_{\text {Drän }} \geqslant 0,1 \mathrm{~m}$ betragen. Konstruktive Hinweise und die Anforderungen an das Dränmaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_draen_min', '{"parameter":"h_draen_min"}'::jsonb, NULL, 'Schichtdicke des Dränmaterials h_Drän ≥ 0,1 m', 9, '{"wert":0.1,"unit":"m","comparator":"≥","modal":"sollte","text":"Die Schichtdicke des Dränmaterials sollte mindestens $h_{\\text {Drän }} \\geqslant 0,1 \\mathrm{~m}$ betragen"}'::jsonb, 'Die Dränage muss mindestens in DN 50 ungedrosselt ausgeführt werden. Die Drosselung erfolgt über den Fließwiderstand des Filtermaterials. Die Schichtdicke des Dränmaterials sollte mindestens $h_{\text {Drän }} \geqslant 0,1 \mathrm{~m}$ betragen. Konstruktive Hinweise und die Anforderungen an das Dränmaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_rbf_min', '{"parameter":"h_rbf_min"}'::jsonb, NULL, 'Mindesteinbautiefe h_RBF ≥ 0,6 m (Aufbau nach Bild 8)', 10, '{"wert":0.6,"unit":"m","comparator":"≥","modal":"möglich","text":"Einbautiefe von lediglich $h_{\\text {RBF }} \\geqslant 0,6 \\mathrm{~m}$ möglich"}'::jsonb, 'In Bild 8 sind die aufgeführten vertikalen Mindestmaße und Proportionen beispielhaft für einen Filterkörper mit Deckschicht dargestellt. Mit diesem Aufbau sind Klein-RBF mit einer Einbautiefe von lediglich $h_{\text {RBF }} \geqslant 0,6 \mathrm{~m}$ möglich, was insbesondere bei flacher Topografie, geringen Gefälleverhältnissen und/oder geringer Tiefenverfügbarkeit vorteilhaft ist.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'a_f_anteil_pct', '{"parameter":"a_f_anteil_pct"}'::jsonb, NULL, 'spezifische Bodenfilteroberfläche A_F = 1,0 % der angeschlossenen befestigten Fläche A_b,a', 11, '{"wert":1,"unit":"%","comparator":"=","modal":"beträgt","text":"Die spezifische Bodenfilteroberfläche beträgt $A_{\\mathrm{F}}=1,0 \\%$ der angeschlossenen befestigten Fläche"}'::jsonb, 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
