INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'a_f_m2_pro_ha', '{"parameter":"a_f_m2_pro_ha"}'::jsonb, NULL, 'A_F = 100 m²/ha A_b,a', 12, '{"wert":100,"unit":"m²/ha","comparator":"=","modal":"entspricht","text":"Dies entspricht $A_{\\mathrm{F}}=100 \\mathrm{~m}^{2} / \\mathrm{ha} A_{\\mathrm{b}, \\mathrm{a}}$"}'::jsonb, 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
