SELECT id, 'eta_afs63_min', '{"parameter":"eta_afs63_min"}'::jsonb, NULL, 'AFS63-Wirkungsgrad η_AFS63 ≥ 95 % (> 85 % der Jahreswassermenge behandelt)', 14, '{"wert":95,"unit":"%","comparator":"≥","modal":"können","text":"AFS63-Wirkungsgrad von $\\eta_{\\mathrm{AFS} 63} \\geqslant 95 \\%$"}'::jsonb, 'Mit dieser Anlagenkonfiguration können bei einer nutzbaren Einstauhöhe von $h_{\mathrm{RR}} \geqslant 0,2 \mathrm{~m}$ und einer Drosselung über den Fließwiderstand des Filtermaterials > $85 \%$ der zufließenden mittleren Jahreswassermenge mit einem AFS63-Wirkungsgrad von $\eta_{\mathrm{AFS} 63} \geqslant 95 \%$ behandelt werden. Aus verfahrenstechnischer Sicht ist bei dieser Anlagenkonfiguration kein weiterer Nachweis erforderlich.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
