SELECT id, 'jahreswassermenge_min_pct', '{"parameter":"jahreswassermenge_min_pct"}'::jsonb, NULL, 'behandelter Anteil der mittleren Jahreswassermenge > 85 %', 15, '{"wert":85,"unit":"%","comparator":">","modal":"können","text":"> $85 \\%$ der zufließenden mittleren Jahreswassermenge"}'::jsonb, 'Mit dieser Anlagenkonfiguration können bei einer nutzbaren Einstauhöhe von $h_{\mathrm{RR}} \geqslant 0,2 \mathrm{~m}$ und einer Drosselung über den Fließwiderstand des Filtermaterials > $85 \%$ der zufließenden mittleren Jahreswassermenge mit einem AFS63-Wirkungsgrad von $\eta_{\mathrm{AFS} 63} \geqslant 95 \%$ behandelt werden. Aus verfahrenstechnischer Sicht ist bei dieser Anlagenkonfiguration kein weiterer Nachweis erforderlich.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
