SELECT id, 'b_krit', '{"parameter":"b_krit"}'::jsonb, NULL, 'maximal zulässige AFS63-Filterflächenbelastung b_krit = 7 kg/(m²·a) (DWA-A 178) — Nachweis für A_F < 1,0 %', 16, '{"wert":7,"unit":"kg/(m²·a)","comparator":"=","modal":"möglich","text":"$b_{\\text {krit }}=7 \\mathrm{~kg} /\\left(\\mathrm{m}^{2} \\cdot \\mathrm{a}\\right)$"}'::jsonb, 'Mit entsprechender Nachweisführung über die zufließende mittlere Jahreswassermenge und der prognostizierten mittleren AFS-Zulaufbelastung (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$ möglich.' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'S5_5_KLEIN'
