SELECT id, 'faellung_filterzulauf', '{"variante_p":"faellung_filterzulauf"}'::jsonb, NULL, 'a) Fällung Filterzulauf', 0, '{"betriebspunkte":"Dosierstation einschließlich Steuerung, Durchflussmessung, Stromversorgung","platzbedarf":"geringfügig erhöht für Dosierstation, Fällmittellagerung und Zufahrt","erfahrungen":"neuartige Anwendung, keine großtechnischen Betriebserfahrungen, derzeit nur im halbtechnischen Versuchsmaßstab untersucht","nachruestung":"bei ausreichender Flächenverfügbarkeit und Stromversorgung möglich","zugabe":"kontinuierlich","wiederverwendung_p":"nicht möglich","ausnutzung":"hohe Ausnutzung bei guter Durchmischung","ausfall":"keine Ausfallzeiten (Ausbilden der Sekundärfilterschicht beachten)"}'::jsonb, '\hline Zusätzliche Betriebspunkte (in Bezug zu Arbeitsblatt DWA-A 178:2019] & Dosierstation einschließlich Steuerung, Durchflussmessung, Stromversorgung & keine & Sorptionsstufe, Zu-/ Ablaufsteuerung, Stromversorgung lerhöhter Energiebedarf) \\
\hline Platzbedarf (in Bezug zu Arbeitsblatt DWA-A 178:2019] & geringfügig erhöht für Dosierstation, Fällmittellagerung und Zufahrt & keine Änderung & erhöht, für Sorptionsstufe und Zu-/Ablaufbauwerke inkl. Pumpwerk und Zufahrt \\
\hline Erfahrungen & neuartige Anwendung, keine großtechnischen Betriebserfahrungen, derzeit nur im halbtechnischen Versuchsmaßstab untersucht & langjährige großtechnische Betriebserfahrungen & neuartige Anwendung, keine großtechnischen Betriebserfahrungen, umfängliche halbtechnische Untersuchungen, Erfahrungen aus Kläranlagenanwendung \\
\hline Nachrüstung & bei ausreichender Flächenverfügbarkeit und Stromversorgung möglich & nur durch (Teil-)Austausch bzw. Aufbereitung und anschließendes Meliorieren des Filtermaterials & bei ausreichenden Flächenverfügbarkeit und Stromversorgung möglich \\
\hline Zugabe Sorptions-/Fällmittel (bezogen auf die Nutzungsdauer) & kontinuierlich & einmalig & periodisch \\
\hline Wiederverwendung Phosphor & nicht möglich & nicht möglich & möglich \\
\hline Ausnutzung Sorptions-/ Fällmittel & hohe Ausnutzung bei guter Durchmischung & geringe bis hohe Ausnutzung in Abhängigkeit der Beschickungsereignisse & hohe Ausnutzung durch vollflächige stoffliche Belastung \\
\hline Ausfall bei Erneuerung & keine Ausfallzeiten (Ausbilden der Sekundärfilterschicht beachten) & Außerbetriebnahme wie bei Inbetriebnahme nach Arbeitsblatt DWA-A 178:2019 gegebenenfalls Teilaustausch des Filtermaterials ausreichend Neubepflanzung nach Austausch des Filtermaterials gegebenenfalls notwendig & keine/geringe Ausfallzeiten beim Wechsel des Sorptionsmaterials (in Abhängigkeit von der Anlagengröße und Drosselabflussspende) \\' FROM regulation_tables WHERE standard_code = 'DWA-M-187' AND edition = '2025-09' AND table_code = 'TABELLE3'
